def solve():
    solutions = []
    for n in range(3, 1000):
        val = 2**n - 3
        if val > 0:
            # Check if val is a power of 5
            # val = 5^k => k = log5(val)
            import math
            k = round(math.log(val, 5))
            if 5**k == val:
                solutions.append((n, k))
    return solutions

print(solve())

